draw((0,0)--(0,1), Arrow);
label("(0,0)", (0,0), SW);
label("(0,1)", (0,1), W);
label("(1,0)", (1,0), S);

fill((0,0)--(1,1)--(.5,1)--cycle, gray(.7));
draw((.5,1)--(.5,.5));
[/asy]

